<script setup lang="ts">
import {computed,ref} from 'vue';
import EmptyState from './EmptyState.vue';
import {gradeShares,type CountPoint} from '../chart-data';
const props=defineProps<{items:CountPoint[]}>(),active=ref<number|null>(null);
const valid=computed(()=>props.items.every(row=>Number.isSafeInteger(row.count)&&row.count>=0));
const shares=computed(()=>valid.value?gradeShares(props.items):[]),total=computed(()=>props.items.reduce((sum,row)=>sum+row.count,0)),circumference=2*Math.PI*70;
const segments=computed(()=>{let offset=0;return shares.value.map(row=>{const segment={...row,offset,length:row.count/total.value*circumference};offset+=segment.length;return segment;});});
</script>
<template><figure class="chart-frame"><p v-if="!valid" class="error" role="alert">职级统计暂不可用，请重新查询。</p><EmptyState v-else-if="!shares.length" text="暂无职级数据" compact/><template v-else><div class="donut-layout"><svg viewBox="0 0 180 180" class="donut-plot" role="group" aria-label="职级比例环形图"><circle cx="90" cy="90" r="70" fill="none" stroke="#eef3fb" stroke-width="25"/><circle v-for="(row,index) in segments" :key="row.name" cx="90" cy="90" r="70" fill="none" :stroke="row.color" stroke-width="25" :stroke-dasharray="`${row.length} ${circumference-row.length}`" :stroke-dashoffset="-row.offset" transform="rotate(-90 90 90)" tabindex="0" role="img" :aria-label="`${row.name}：${row.count}人，占${row.percent}%`" @focus="active=index" @blur="active=null" @mouseenter="active=index" @mouseleave="active=null"><title>{{row.name}}：{{row.count}}人，{{row.percent}}%</title></circle><text x="90" y="87" text-anchor="middle" class="donut-total">{{total}}</text><text x="90" y="110" text-anchor="middle" class="chart-label">统计人数</text></svg><ul class="chart-legend"><li v-for="row in shares" :key="row.name"><i :style="{background:row.color}"/><span>{{row.name}}</span><b>{{row.count}} 人</b><small>{{row.percent}}%</small></li></ul></div><figcaption class="chart-readout" aria-live="polite">{{active!==null&&shares[active]?`${shares[active].name}：${shares[active].count}人，占${shares[active].percent}%`:'职级人数及占比'}}</figcaption></template></figure></template>
